CREATE TYPE public.app_role AS ENUM ('admin', 'moderator', 'customer');
CREATE TYPE public.product_status AS ENUM ('available', 'low_stock', 'coming_soon', 'out_of_stock', 'temporarily_unavailable', 'archived');
CREATE TYPE public.order_status AS ENUM ('pending', 'processing', 'paid', 'failed', 'cancelled', 'refunded', 'fulfilled', 'completed');
CREATE TABLE public.profiles (id UUID PRIMARY KEY, display_name TEXT, phone TEXT, delivery_email TEXT, preferences JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role; ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own profile read" ON public.profiles FOR SELECT TO authenticated USING (auth.uid() = id); CREATE POLICY "Own profile insert" ON public.profiles FOR INSERT TO authenticated WITH CHECK (auth.uid() = id); CREATE POLICY "Own profile update" ON public.profiles FOR UPDATE TO authenticated USING (auth.uid() = id) WITH CHECK (auth.uid() = id);
CREATE TABLE public.user_roles (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL, role public.app_role NOT NULL DEFAULT 'customer', UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role; ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY; CREATE POLICY "Own roles read" ON public.user_roles FOR SELECT TO authenticated USING (auth.uid() = user_id);
CREATE OR REPLACE FUNCTION public.has_role(_user_id UUID, _role public.app_role) RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$; GRANT EXECUTE ON FUNCTION public.has_role(UUID, public.app_role) TO authenticated;
CREATE TABLE public.categories (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), slug TEXT UNIQUE NOT NULL, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', is_published BOOLEAN NOT NULL DEFAULT false, sort_order INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
GRANT SELECT ON public.categories TO anon, authenticated; GRANT INSERT, UPDATE, DELETE ON public.categories TO authenticated; GRANT ALL ON public.categories TO service_role; ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY; CREATE POLICY "Published categories read" ON public.categories FOR SELECT TO anon, authenticated USING (is_published OR public.has_role(auth.uid(),'admin')); CREATE POLICY "Admin categories" ON public.categories FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TABLE public.products (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), category_id UUID REFERENCES public.categories(id), slug TEXT UNIQUE NOT NULL, name TEXT NOT NULL, brand TEXT NOT NULL, summary TEXT NOT NULL, description TEXT NOT NULL, platform TEXT, region TEXT NOT NULL DEFAULT 'Global', currency TEXT NOT NULL DEFAULT 'NPR', delivery_method TEXT NOT NULL DEFAULT 'Manual digital fulfilment', delivery_time TEXT NOT NULL DEFAULT 'Confirmed after order review', requirements JSONB NOT NULL DEFAULT '[]'::jsonb, redemption_instructions TEXT, refund_eligibility TEXT NOT NULL DEFAULT 'Reviewed before fulfilment', tags TEXT[] NOT NULL DEFAULT '{}', status public.product_status NOT NULL DEFAULT 'coming_soon', badges TEXT[] NOT NULL DEFAULT '{}', image_url TEXT, seo_title TEXT NOT NULL, seo_description TEXT NOT NULL, is_published BOOLEAN NOT NULL DEFAULT false, featured_rank INTEGER, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
GRANT SELECT ON public.products TO anon, authenticated; GRANT INSERT, UPDATE, DELETE ON public.products TO authenticated; GRANT ALL ON public.products TO service_role; ALTER TABLE public.products ENABLE ROW LEVEL SECURITY; CREATE POLICY "Published products read" ON public.products FOR SELECT TO anon, authenticated USING (is_published OR public.has_role(auth.uid(),'admin')); CREATE POLICY "Admin products" ON public.products FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TABLE public.product_variants (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), product_id UUID NOT NULL REFERENCES public.products(id) ON DELETE CASCADE, sku TEXT UNIQUE NOT NULL, name TEXT NOT NULL, price_minor INTEGER NOT NULL CHECK(price_minor>=0), currency TEXT NOT NULL DEFAULT 'NPR', stock_quantity INTEGER, status public.product_status NOT NULL DEFAULT 'available', is_default BOOLEAN NOT NULL DEFAULT false, sort_order INTEGER NOT NULL DEFAULT 0);
GRANT SELECT ON public.product_variants TO anon, authenticated; GRANT INSERT, UPDATE, DELETE ON public.product_variants TO authenticated; GRANT ALL ON public.product_variants TO service_role; ALTER TABLE public.product_variants ENABLE ROW LEVEL SECURITY; CREATE POLICY "Published variants read" ON public.product_variants FOR SELECT TO anon, authenticated USING (EXISTS(SELECT 1 FROM public.products p WHERE p.id=product_id AND (p.is_published OR public.has_role(auth.uid(),'admin')))); CREATE POLICY "Admin variants" ON public.product_variants FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TABLE public.orders (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), order_number TEXT UNIQUE NOT NULL, user_id UUID, guest_email TEXT, guest_phone TEXT, verification_hash TEXT NOT NULL, status public.order_status NOT NULL DEFAULT 'pending', currency TEXT NOT NULL DEFAULT 'NPR', subtotal_minor INTEGER NOT NULL CHECK(subtotal_minor>=0), discount_minor INTEGER NOT NULL DEFAULT 0 CHECK(discount_minor>=0), total_minor INTEGER NOT NULL CHECK(total_minor>=0), customer_details JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.orders TO authenticated; GRANT ALL ON public.orders TO service_role; ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY; CREATE POLICY "Own orders read" ON public.orders FOR SELECT TO authenticated USING (auth.uid()=user_id OR public.has_role(auth.uid(),'admin')); CREATE POLICY "Own orders insert" ON public.orders FOR INSERT TO authenticated WITH CHECK (auth.uid()=user_id); CREATE POLICY "Admin orders" ON public.orders FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TABLE public.wishlist_items (user_id UUID NOT NULL, product_id UUID NOT NULL REFERENCES public.products(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(user_id,product_id)); GRANT SELECT,INSERT,DELETE ON public.wishlist_items TO authenticated; GRANT ALL ON public.wishlist_items TO service_role; ALTER TABLE public.wishlist_items ENABLE ROW LEVEL SECURITY; CREATE POLICY "Own wishlist" ON public.wishlist_items FOR ALL TO authenticated USING (auth.uid()=user_id) WITH CHECK (auth.uid()=user_id);
CREATE TABLE public.reviews (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), product_id UUID NOT NULL REFERENCES public.products(id) ON DELETE CASCADE, user_id UUID NOT NULL, rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5), body TEXT NOT NULL, is_verified_purchase BOOLEAN NOT NULL DEFAULT false, is_approved BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now()); GRANT SELECT ON public.reviews TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.reviews TO authenticated; GRANT ALL ON public.reviews TO service_role; ALTER TABLE public.reviews ENABLE ROW LEVEL SECURITY; CREATE POLICY "Approved reviews read" ON public.reviews FOR SELECT TO anon,authenticated USING (is_approved OR user_id=auth.uid() OR public.has_role(auth.uid(),'admin')); CREATE POLICY "Own review submit" ON public.reviews FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND NOT is_approved AND NOT is_verified_purchase); CREATE POLICY "Admin review moderation" ON public.reviews FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.support_tickets (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID, order_number TEXT, issue_type TEXT NOT NULL, description TEXT NOT NULL, screenshot_path TEXT, status TEXT NOT NULL DEFAULT 'open', created_at TIMESTAMPTZ NOT NULL DEFAULT now()); GRANT SELECT,INSERT ON public.support_tickets TO authenticated; GRANT ALL ON public.support_tickets TO service_role; ALTER TABLE public.support_tickets ENABLE ROW LEVEL SECURITY; CREATE POLICY "Own tickets" ON public.support_tickets FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin')); CREATE POLICY "Own ticket submit" ON public.support_tickets FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid()); CREATE POLICY "Admin tickets" ON public.support_tickets FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));